eader class="review-header">
        <div class="aspect-switcher" role="tablist" aria-label="Review aspect">
          @for (candidate of availableMeta(); track candidate.kind) {
            <button role="tab" [attr.aria-selected]="activeKind() === candidate.kind" [class.active]="activeKind() === candidate.kind" (click)="selectKind(candidate.kind)">
              {{ candidate.kind }} <b>{{ candidate.grade.band }}</b>
              <i class="status" [class]="'status ' + (selectedNode()?.kinds?.[candidate.kind]?.direct ?? 'missing')"></i>
